import re, collections
seqs={}; name=None
for line in open('region.fasta'):
    line=line.strip()
    if line.startswith('>'): name=line[1:]; seqs[name]=''
    else: seqs[name]+=line
seq=seqs[list(seqs)[0]].upper()

# 1. GC per 250bp window
print("GC% per 250bp window:")
for i in range(0,len(seq)-249,250):
    w=seq[i:i+250]
    print(f"  {i+1}-{i+250}: {100*(w.count('G')+w.count('C'))/250:.1f}")

# homopolymer runs
print("\nHomopolymer runs >=6:")
for b in 'ACGT':
    for m in re.finditer(b*6,seq):
        # extend
        s=m.start(); e=s+6
        while e<len(seq) and seq[e]==b: e+=1
        while s>0 and seq[s-1]==b: s-=1
        print(f"  {b}x{e-s} at {s+1}-{e}")

# direct repeats (all pairs, k>=14, allowing 0 gaps)
print("\nDirect repeats k>=14:")
seen=collections.defaultdict(list)
for k in [14]:
    for i in range(len(seq)-k+1):
        w=seq[i:i+k]
        seen[w].append(i+1)
for w,pos in seen.items():
    if len(pos)>1:
        print(f"  {pos}")

# dyad symmetry / hairpins: stem>=10, loop 4-12, perfect
def hairpins(s, minstem=10, minloop=4, maxloop=12):
    out=[]
    for i in range(len(s)-1):
        for loop in range(minloop,maxloop+1):
            j=i+loop
            stem=0
            L=i
            R=j
            while L>=0 and R<len(s) and s[L]==({'A':'T','T':'A','G':'C','C':'G'}[s[R]]):
                stem+=1; L-=1; R+=1
            if stem>=minstem:
                out.append((L+2,R+1,stem,loop))
    return out
print("\nHairpins (stem>=10):")
for a,b,stem,lp in hairpins(seq,10,4,14):
    print(f"  left {a} right {b} stem {stem} loop {lp}")
